new file mode 100644
index 0000000000000000000000000000000000000000..e4bb7d0e70dcdc01108e779a363dd0a9b0c7c427
--- /dev/null
+++ b/internal/library/rtk_history.go
@@ -0,0 +1,128 @@
+package library
+
+import (
+	"context"
+	"fmt"
+	"os"
+	"path/filepath"
+	"strings"
+
+	"github.com/pelletier/go-toml/v2"
+	"github.com/yetone/magpie/internal/appdir"
+)
+
+// rtkCodexHistory recovers an empty default count from Codex's MSIX
+// history. RTK reads the database itself; no files or settings are moved.
+func rtkCodexHistory(ctx context.Context, bin string) (*RTKGain, []RTKDay, string) {
+	chosen, err := rtkHistoryChosen()
+	if err != nil {
+		return nil, nil, err.Error()
+	}
+	if chosen {
+		return nil, nil, ""
+	}
+	paths, err := rtkCodexHistoryPaths(appdir.Getenv("LOCALAPPDATA"))
+	if err != nil {
+		return nil, nil, "Codex RTK history: " + err.Error()
+	}
+	var gain *RTKGain
+	var days []RTKDay
+	for _, path := range paths {
+		g, d, why := rtkGainAt(ctx, bin, path)
+		if why != "" {
+			return nil, nil, fmt.Sprintf("Codex RTK history %s: %s", path, why)
+		}
+		if g == nil {
+			continue
+		}
+		if gain != nil {
+			return nil, nil, "More than one Codex app RTK history has records. Set tracking.database_path in RTK's config to the history to display."
+		}
+		g.History = path
+		gain, days = g, d
+	}
+	return gain, days, ""
+}
+
+// A user-selected database, including an empty one, must not be replaced.
+// An unreadable configuration is unknown, never permission to choose one.
+func rtkHistoryChosen() (bool, error) {
+	for _, key := range []string{"RTK_DB_PATH", "RTK_CONFIG_DIR"} {
+		if _, set := os.LookupEnv(key); set {
+			return true, nil
+		}
+	}
+	roaming := appdir.Getenv("APPDATA")
+	if roaming == "" {
+		return true, nil
+	}
+	path := filepath.Join(roaming, "rtk", "config.toml")
+	raw, err := os.ReadFile(path)
+	if os.IsNotExist(err) {
+		return false, nil
+	}
+	if err != nil {
+		return false, fmt.Errorf("RTK configuration: %w", err)
+	}
+	var config struct {
+		Tracking struct {
+			DatabasePath *string `toml:"database_path"`
+			Enabled      *bool   `toml:"enabled"`
+		} `toml:"tracking"`
+	}
+	if err := toml.Unmarshal(raw, &config); err != nil {
+		return false, fmt.Errorf("RTK configuration: %w", err)
+	}
+	return config.Tracking.DatabasePath != nil || (config.Tracking.Enabled != nil && !*config.Tracking.Enabled), nil
+}
+
+// App-data folders name package families, not versions or one publisher.
+// A hard link or a merged MSIX view of the default file is queried once.
+func rtkCodexHistoryPaths(local string) ([]string, error) {
+	if local == "" {
+		return nil, nil
+	}
+	packages := filepath.Join(local, "Packages")
+	entries, err := os.ReadDir(packages)
+	if os.IsNotExist(err) {
+		return nil, nil
+	}
+	if err != nil {
+		return nil, err
+	}
+	var seen []os.FileInfo
+	if info, err := os.Stat(filepath.Join(local, "rtk", "history.db")); err == nil {
+		seen = append(seen, info)
+	} else if !os.IsNotExist(err) {
+		return nil, err
+	}
+	var paths []string
+	for _, entry := range entries {
+		if !strings.HasPrefix(entry.Name(), "OpenAI.Codex_") {
+			continue
+		}
+		path := filepath.Join(packages, entry.Name(), "LocalCache", "Local", "rtk", "history.db")
+		info, err := os.Stat(path)
+		if os.IsNotExist(err) {
+			continue
+		}
+		if err != nil {
+			return nil, err
+		}
+		if !info.Mode().IsRegular() {
+			return nil, fmt.Errorf("%s is not a regular history file", path)
+		}
+		duplicate := false
+		for _, previous := range seen {
+			if os.SameFile(previous, info) {
+				duplicate = true
+				break
+			}
+		}
+		if !duplicate {
+			seen = append(seen, info)
+			paths = append(paths, path)
+		}
+	}
+	return paths, nil
+}
