+const emptyRTKHistory = `{"summary":{"total_commands":0,"total_input":0,"total_saved":0,"avg_savings_pct":0}}`
+const savedRTKHistory = `{"summary":{"total_commands":42,"total_input":9000,"total_saved":8000,"avg_savings_pct":88.9},"daily":[{"date":"2026-11-01","commands":42,"input_tokens":9000,"saved_tokens":8000,"savings_pct":88.9}]}`
+
+func historyRTK(t *testing.T) (bin, local, roaming string) {
+	t.Helper()
+	if runtime.GOOS != "windows" {
+		t.Skip("MSIX history discovery is Windows-only")
+	}
+	root := filepath.Join(t.TempDir(), "RTK home & data")
+	local, roaming = filepath.Join(root, "Local"), filepath.Join(root, "Roaming")
+	t.Setenv("LOCALAPPDATA", local)
+	t.Setenv("APPDATA", roaming)
+	for _, key := range []string{"RTK_DB_PATH", "RTK_CONFIG_DIR"} {
+		old, existed := os.LookupEnv(key)
+		os.Unsetenv(key)
+		t.Cleanup(func() {
+			if existed {
+				os.Setenv(key, old)
+			} else {
+				os.Unsetenv(key)
+			}
+		})
+	}
+	defaultHistory := filepath.Join(local, "rtk", "history.db")
+	write(t, defaultHistory, emptyRTKHistory)
+	t.Setenv("RTK_HISTORY_TEST_DEFAULT", defaultHistory)
+	bin = filepath.Join(root, "rtk.cmd")
+	write(t, bin, "@echo off\r\nif not \"%1\"==\"gain\" exit /b 2\r\nif defined RTK_DB_PATH (\r\n type \"%RTK_DB_PATH%\"\r\n) else (\r\n type \"%RTK_HISTORY_TEST_DEFAULT%\"\r\n)\r\nexit /b 0\r\n")
+	return bin, local, roaming
+}
+
+func codexRTKHistory(t *testing.T, local, family, content string) string {
+	t.Helper()
+	path := filepath.Join(local, "Packages", family, "LocalCache", "Local", "rtk", "history.db")
+	write(t, path, content)
+	return path
+}
+
+func gainHistoryPath(t *testing.T, gain *RTKGain) string {
+	t.Helper()
+	raw, err := json.Marshal(gain)
+	if err != nil {
+		t.Fatal(err)
+	}
+	var view struct{ History string }
+	if err := json.Unmarshal(raw, &view); err != nil {
+		t.Fatal(err)
+	}
+	return view.History
+}
+
+func TestRTKGainCodexAppHistory(t *testing.T) {
+	bin, local, roaming := historyRTK(t)
+	source := codexRTKHistory(t, local, "OpenAI.Codex_publisher", savedRTKHistory)
+	gain, days, why := rtkGain(bin)
+	if gain == nil || gain.Commands != 42 || gain.Saved != 8000 || len(days) != 1 || why != "" {
+		t.Fatalf("Codex app history was not recovered: gain=%+v days=%+v error=%q", gain, days, why)
+	}
+	if got := gainHistoryPath(t, gain); got != source {
+		t.Fatalf("history source=%q, want %q", got, source)
+	}
+	if _, err := os.Stat(filepath.Join(roaming, "rtk", "config.toml")); !os.IsNotExist(err) {
+		t.Fatalf("reading history changed RTK configuration: %v", err)
+	}
+	config := filepath.Join(roaming, "rtk", "config.toml")
+	defaults := "[tracking]\nenabled = true\nhistory_days = 90\n"
+	write(t, config, defaults)
+	gain, _, why = rtkGain(bin)
+	if gain == nil || gainHistoryPath(t, gain) != source || why != "" {
+		t.Fatalf("default RTK configuration blocked recovery: gain=%+v error=%q", gain, why)
+	}
+	for path, want := range map[string]string{config: defaults, source: savedRTKHistory, filepath.Join(local, "rtk", "history.db"): emptyRTKHistory} {
+		got, err := os.ReadFile(path)
+		if err != nil || string(got) != want {
+			t.Fatalf("history was modified: %s: %v", path, err)
+		}
+	}
+}
+
+func TestRTKGainKeepsChosenHistory(t *testing.T) {
+	for _, mode := range []string{"default has records", "environment override", "configuration override", "empty environment override", "config directory override", "tracking disabled"} {
+		t.Run(mode, func(t *testing.T) {
+			bin, local, roaming := historyRTK(t)
+			codexRTKHistory(t, local, "OpenAI.Codex_publisher", savedRTKHistory)
+			wantRecords := false
+			switch mode {
+			case "default has records":
+				write(t, filepath.Join(local, "rtk", "history.db"), savedRTKHistory)
