+			case "environment override":
+				custom := filepath.Join(local, "custom.db")
+				write(t, custom, emptyRTKHistory)
+				t.Setenv("RTK_DB_PATH", custom)
+			case "configuration override":
+				config := filepath.Join(roaming, "rtk", "config.toml")
