+			case "empty environment override":
+				t.Setenv("RTK_DB_PATH", "")
+			case "config directory override":
+				t.Setenv("RTK_CONFIG_DIR", roaming)
+			case "tracking disabled":
+				write(t, filepath.Join(roaming, "rtk", "config.toml"), "[tracking]\nenabled = false\nhistory_days = 90\n")
