+			}
+			if gain != nil && gainHistoryPath(t, gain) != "" {
+				t.Fatal("default history was labelled as Codex's private history")
+			}
+		})
+	}
+}
+
+func TestRTKGainCodexHistoryAmbiguousOrUnreadable(t *testing.T) {
+	for _, mode := range []string{"two populated histories", "unreadable history", "invalid configuration"} {
+		t.Run(mode, func(t *testing.T) {
