+func TestRTKGainCodexHistoryEmptyAndAliases(t *testing.T) {
+	for _, mode := range []string{"no app history", "empty app history", "unrelated app", "empty plus populated", "same file twice", "same as default"} {
+		t.Run(mode, func(t *testing.T) {
